 @Bean @org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name="NIGSON_CAREERS_ANTISPAM_MODE",havingValue="mock") CareerService.AntiSpamVerifier localCareerAntiSpam(Environment e){if(!Set.of("local","test").contains(e.getRequiredProperty("APP_ENV")))throw new IllegalArgumentException("CAREER_MOCK_ANTISPAM_LOCAL_ONLY");return new LocalCareerAntiSpamMock(e.getRequiredProperty("NIGSON_CAREERS_LOCAL_ANTISPAM_HMAC_KEY"));}
 @Bean @org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name="NIGSON_CAREERS_ENABLED",havingValue="true") CareerSecrets careerSecrets(Environment e){if(!e.getProperty("NIGSON_SECURITY_ENABLED",Boolean.class,false))throw new IllegalArgumentException("CAREER_SECURITY_REQUIRED");String env=e.getRequiredProperty("APP_ENV"),revision=e.getRequiredProperty("NIGSON_CAREERS_CIPHER_REVISION"),localHash=e.getProperty("NIGSON_CAREERS_LOCAL_HASH_KEY",""),localCipher=e.getProperty("NIGSON_CAREERS_LOCAL_CIPHER_KEY","");if(!localHash.isBlank()||!localCipher.isBlank())return CareerKeys.load(null,env,e.getRequiredProperty("NIGSON_CAREERS_HASH_KEY_VERSION",Integer.class),revision,e.getProperty("NIGSON_CAREERS_KMS_KEY_ARN",""),e.getProperty("NIGSON_CAREERS_WRAPPED_HASH_KEY",""),e.getProperty("NIGSON_CAREERS_WRAPPED_CIPHER_KEY",""),localHash,localCipher,e.getProperty("NIGSON_CAREERS_PREVIOUS_CIPHER_KEYS","{}"));try(var kms=software.amazon.awssdk.services.kms.KmsClient.create()){return CareerKeys.load(kms,env,e.getRequiredProperty("NIGSON_CAREERS_HASH_KEY_VERSION",Integer.class),revision,e.getProperty("NIGSON_CAREERS_KMS_KEY_ARN",""),e.getProperty("NIGSON_CAREERS_WRAPPED_HASH_KEY",""),e.getProperty("NIGSON_CAREERS_WRAPPED_CIPHER_KEY",""),localHash,localCipher,e.getProperty("NIGSON_CAREERS_PREVIOUS_CIPHER_KEYS","{}"));}}
 @Bean CareerService careerService(JdbcTemplate jdbc,PlatformStore store,AuditWriter audit,org.springframework.beans.factory.ObjectProvider<CareerSecrets> secret,org.springframework.transaction.PlatformTransactionManager manager,Environment e,org.springframework.beans.factory.ObjectProvider<CareerService.AntiSpamVerifier> spam){return new CareerService(jdbc,store,audit,secret.getIfAvailable(),manager,Clock.systemUTC(),e.getProperty("NIGSON_CAREERS_RETENTION_DAYS",Integer.class,0),e.getProperty("NIGSON_CAREERS_PRIVACY_POLICY_VERSION",""),e.getProperty("NIGSON_CAREERS_SHEET_RECIPIENT_GROUP",""),Set.copyOf(Arrays.asList(e.getProperty("NIGSON_CAREERS_SHEET_ANSWER_FIELDS","").split(","))),spam.getIfAvailable());}
